// The lanes service returns eval_metrics.analyze() as the response BODY.
// A refused ledger (chain_ok:false) or a failed lane call escalates to warn —
// the lane must never look healthy just because the call did not come back.
const d = $input.first().json || {};
const NL = String.fromCharCode(10);
if (d.chain_ok === false || (!d.metrics && !d.note)) {
  return [{ json: {
    severity: 'warn',
    title: 'Eval lane: LEDGER REFUSED or lane call failed',
    message: ['chain_ok=' + d.chain_ok,
              d.error || JSON.stringify(d).slice(0, 400),
              'Run scripts/verify_audit.py.'].join(NL),
    source: 'eval-drift'
  } }];
}
if (!d.metrics) {
  return [{ json: { severity: 'info', title: 'Eval lane: no data in window',
    message: d.note || 'no decisions in the eval window yet.', source: 'eval-drift' } }];
}
const m = d.metrics;
const flags = d.drift_flags || [];
const warn = flags.length > 0;
const warnLines = flags.map(function (f) { return '[' + f.metric + '] ' + f.message; }).join(NL);
// HARNESS: which CONFIGURATION produced the result, not which model. Reported
// only when at least two configs cleared the sample floor — below that the
// breakdown is descriptive and ranking it would be inventing a signal.
const h = d.harness || {};
const cmp = (h.comparable || []);
let harnessLine;
if (cmp.length >= 2) {
  const best = (h.configs || []).filter(function (c) { return c.sufficient; })
    .sort(function (a, b) { return (b.quality_held_pct || 0) - (a.quality_held_pct || 0); })[0];
  harnessLine = 'Harness: ' + cmp.length + ' comparable configs; best held ' +
    (best ? best.quality_held_pct + '% at $' + best.cost_per_held_usd + '/held (' + best.config + ')' : 'n/a');
} else {
  harnessLine = 'Harness: ' + (h.configs || []).length + ' config(s) seen, ' +
    'too few runs each to compare (floor n=' + (h.min_n || '?') + ').';
}

const lines = [
  'Agentic leverage (proxy): ' + m.agentic_leverage_pct + '%  (' + m.leverage_numerator + '/' + m.attempted + ')',
  'Verify-pass: ' + m.verify_pass_pct + '%   Change-failure: ' + m.change_failure_pct + '%',
  'Block rate: ' + m.block_rate_pct + '%   PII-block: ' + m.pii_block_pct + '%   Approval: ' + m.approval_pct + '%',
  harnessLine,
  '',
  warn ? ('DRIFT (' + flags.length + '):' + NL + warnLines) : 'No drift flags (key metrics within threshold).',
  '',
  'window ' + d.window.since + ' -> ' + d.window.until + '  n=' + d.records_in_window
];
return [{ json: {
  severity: warn ? 'warn' : 'info',
  title: 'Eval lane: leverage ' + m.agentic_leverage_pct + '%, verify-pass ' + m.verify_pass_pct + '%' + (warn ? (' - ' + flags.length + ' drift flag(s)') : ''),
  message: lines.join(NL),
  source: 'eval-drift'
} }];
